-- 2. 经纬度转换为 Point / SRID 4326，并写入最终 stops 表
INSERT INTO public.stops (stop_id, stop_name, longitude, latitude, geom)
SELECT
    stop_id,
    stop_name,
    longitude,
    latitude,
    ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)::geometry(Point, 4326)
FROM public.stops_import_raw
ON CONFLICT (stop_id) DO UPDATE SET
    stop_name = EXCLUDED.stop_name,
    longitude = EXCLUDED.longitude,
    latitude = EXCLUDED.latitude,
    geom = EXCLUDED.geom;

