-- 只读验证
SELECT 'routes' AS table_name, COUNT(*) AS row_count FROM public.routes
UNION ALL SELECT 'stops', COUNT(*) FROM public.stops
UNION ALL SELECT 'route_stops', COUNT(*) FROM public.route_stops
ORDER BY table_name;

SELECT ST_GeometryType(geom) AS geometry_type, ST_SRID(geom) AS srid, COUNT(*) AS row_count
FROM public.stops
GROUP BY ST_GeometryType(geom), ST_SRID(geom);
